package syncing

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

// Expected hashes were independently generated by Python hashlib, using the
// contract's fixed envelope field order and raw (not hex text) hash bytes.
func TestPageManifestCrossLanguageFixture(t *testing.T) {
	b, err := os.ReadFile("../../../../contracts/fixtures/page-manifest.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Fragments []struct {
			Envelope       Envelope `json:"envelope"`
			EnvelopeSHA256 string   `json:"envelopeSHA256"`
			ManifestSHA256 string   `json:"manifestSHA256"`
		} `json:"fragments"`
	}
	if err = json.Unmarshal(b, &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Fragments) != 2 {
		t.Fatal("fixture must have two ordered fragments")
	}
	chain := make([]byte, sha256.Size)
	for _, f := range fixture.Fragments {
		if err = f.Envelope.Validate(); err != nil {
			t.Fatal(err)
		}
		_, digest := f.Envelope.Canonical()
		if hex.EncodeToString(digest) != f.EnvelopeSHA256 {
			t.Fatal("envelope hash differs from independent fixture")
		}
		h := sha256.Sum256(append(chain, digest...))
		chain = h[:]
		if hex.EncodeToString(chain) != f.ManifestSHA256 {
			t.Fatal("page manifest differs from independent fixture")
		}
	}
}
